        const=max(rc) if diag=='main' else max(ac)
        print(f'   {name}={diag} const={const} rows{min(r for r,c in S)}-{max(r for r,c in S)} cols{min(c for r,c in S)}-{max(c for r,c in S)} | len={len(S)}')
    H,W=I.shape
