def solve_isom(n):
    gi,go,bg,S,R=parts(n)
    Sset=set(S); Rset=frozenset(R)
    # all 8 dihedral transforms of S (rotations + reflections), with any translation allowed.
    def rots(ps):
        ps=list(map(tuple,ps)); out=[]; cur=[(r,c) for r,c in ps]
        for _ in range(4):
            p=tuple(sorted(cur))
            out.append(p)
            cur=[(y[-1],-x) if False else (c,-r) for r,c in cur]   # rotate 90: (r,c)->(c,-r) ... careful with negative
            # better: rotate about origin: (r,c)->(-c,r)
            cur=[(-c,r) for r,c in cur]
        return set(out)
    def reflect(ps):
        return {(c,-r) for r,c in ps}
    base=set(Sset)
    out=set()
    for p in rots(base):
        out.add(frozenset(p)); out.update({frozenset((c,-r) for r,c in p)})
    sols=[]
    for d in out:
        dr=min(r for r,c in d)-min(r for r,c in Sset)
        dc=min(c for r,c in d)-min(c for r,c in Sset)
        t=frozenset((r+dr,c+dc) for r,c in d)
        if t==Rset: sols.append(((dr,dc),sorted(d)))
    return sols
