# Clean isometry enumeration: all 8 transforms of S, translated so bbox starts at (0,0), match any subset of R (R may be larger than |S|).
def dihedral(S):
    ps=set(S)
    out=[]
    cur=[p for p in ps]
    for _ in range(4):
        b=frozenset(cur); out.append(b)
        cur=[(y[1],-y[0]) for y in cur]
    return out
def transform(S,R):
    sols=[]
    for d in dihedral(frozenset(S)):
        # normalize bounding box offset
        rs=[r for r,c in d]; cs=[c for r,c in d]
        r0=min(rs); c0=min(cs)
        t=frozenset((r-r0,c-c0) for r,c in d)
        if t <= set(R):
            sols.append(t)
    return sols
