    L=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=sc and ((kind=='df' and r-c==param) or (kind=='ac' and r+c==param))]
    def mind(p):
        r,c=p
        return min(abs(r-sr)+abs(c-sc_) for sr,sc_ in stcells)
    best=[p for p in L if mind(p)==min(mind(p))]
    anchor=max(best,key=lambda p:(p[0],p[1]))
    out=[row[:] for row in g]
    dirs=[(1,1),(1,-1),(-1,1),(-1,-1)]
    for dr,dc in dirs:
