import collections
def f(g):
    g=[list(r) for r in g]
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for row in g for x in row)
    bg,sc,mcol=[c for c,_ in cnt.most_common()][:3]
    stcells=set((r,c) for r in range(H) for c in range(W) if g[r][c]==sc)
    ms=[(r,c) for r in range(H) for c in range(W) if g[r][c]==mcol]
    df={p[0]-p[1] for p in ms}; ac={p[0]+p[1] for p in ms}
    if len(df)==1: param=list(df)[0]; ok=lambda r,c:r-c==param
    else: param=list(ac)[0]; ok=lambda r,c:r+c==param
    # candidate non-stripe points on the line
    cand=[]
    for r in range(H):
        if ok(r,r-r+param) if False else None: pass
    for r in range(H):
        c = param if (ok.__class__ is None) else (lambda k:[k],[k])(lambda k:(param if False else lambda r,c: c-k)(0,0))(None,0)
    if ok==lambda r,c:r-c==param:
        for r in range(H):
            c=r-param
            cand.append((r,c)) if g[r][c]!=sc else None
    else:
        for c in range(W):
            r=param-c
            cand.append((r,c)) if g[r][c]!=sc else None
    def mind(p):
        sr,sc_=p
        return min(abs(sr-q[0])+abs(sc_-q[1]) for q in stcells)
    anchor=min(cand,key=lambda p:(mind(p),-p[0]))
    st_rows=min(q[0] for q in stcells); st_cols=min(q[1] for q in stcells)
    rows=[q[0] for q in stcells]; cols=[q[1] for q in stcells]
    h=max(rows)-min(rows); w=max(cols)-min(cols)
    if h==0 or w>=h:   # horizontal band -> vertical axis away
        sy=1 if anchor[0]>median(rows) else -1
    else:              # vertical band
        sx=1 if anchor[1]>median(cols) else -1
    def allow(dr,dc):
        if h==0 or w>=h: return sy*dr>0
        else: return sx*dc>0
    out=[row[:] for row in g]
    for dr,dc in [(1,1),(1,-1),(-1,1),(-1,-1)]:
        if allow(dr,dc):
            r,c=anchor[0]+dr,anchor[1]+dc
            while 0<=r<H and 0<=c<W and g[r][c]==bg:
                out[r][c]=3; r+=dr; c+=dc
    return out
